import React, { useState } from "react";
import { useTranslation, Link } from "gatsby-plugin-react-i18next";
import menuData from "../data/data.json";
import Logo from "../components/logo";
import { NavigationProps } from "../interfaces";
import menu from "../../static/menu.svg";
import close from "../../static/close.svg";

const Navigation: React.FC<NavigationProps> = ({
}: NavigationProps) => {
  const { t } = useTranslation();
  const [isOpen, setIsOpen] = useState(false);
  const menuItems = menuData.menu;

  // Split menu items into two halves for left and right alignment
  const [moved, setMoved] = useState(false);

  const toggleMenu = () => {
    setMoved(!moved);
    setIsOpen(!isOpen);
  };

  return (
    <nav className="fixed h-[3.75rem] w-full px-0 text-Tofu z-50">
      <div className="flex justify-between items-center w-full sm:px-[3.75rem] h-full bg-black/20 backdrop-blur-xl">
        {/* Centered Logo */}
        <a href="/" className="flex items-center w-[123px] h-[20px] ml-4 sm:ml-0">
          <Logo />
        </a>      
        {/* Desktop Menu */}
        <div className="hidden md:flex justify-end">
          <ul className="flex space-x-6  min-w-full">
            {menuItems.map((item, index) => (
              <li key={index}>
                <a
                  href={item === "partners" ? "/partners" : `/#${item}`}
                  className={`relative text-white nav-bar uppercase after:content-[''] after:absolute after:left-0 after:bottom-[-2px] after:w-full after:h-[2px] after:bg-current after:scale-x-0 after:transition-transform after:origin-left hover:after:scale-x-100`}
                >
                  {t(`menu.${item}`)}
                </a>
              </li>
            ))}
          </ul>
        </div>

        {/* Mobile Button */}
        <button onClick={toggleMenu} className="sm:hidden mr-4">
          {isOpen ? <img src={close} /> : <img src={menu} />}
        </button>
      </div>

      {/* Mobile Menu */}
      <div
        className={`transition-transform top-[-300px] duration-700 ease-in-out transform z-[-1] absolute w-full ${
          moved ? "translate-y-[359px]" : "translate-y-0"
        }`}
      >
        <ul className="absolute z-40 left-0 w-full bg-white/30 !backdrop-blur-md md:hidden shadow-lg">
          {menuItems
            .filter((item) => item !== "_")
            .map((item, index) => (
              <li
                key={index}
                className={`p-5 ${
                  index < menuItems.length - 1 ? "border-b border-white/20" : ""
                }`}
              >
                <a
                  href={item === "partners" ? "/partners" : `/#${item}`}
                    onClick={() => {
                      setIsOpen(false);
                      setMoved(false);
                    }}
                  className={`text-DarkGrayText body-mob block`}
                >
                  {t(`menu.${item}`)}
                </a>
              </li>
            ))}
        </ul>
      </div>
    </nav>
  );
};

export default Navigation;
